var FT={"Atmokinesis":{"cat":"G","hb":"UA24","d":"Change damage to Lightning. Shocking Grasp, Fog Cloud, Gust of Wind.","full":"**Lightning Jolt.** Once per turn, when you cast a spell or hit with an attack roll and deal Bludgeoning, Piercing, Slashing, or Psychic damage, you can change the damage type to Lightning.\n**Psionic Talent.** You know the Shocking Grasp cantrip. You always have Fog Cloud prepared. At character level 3 you also always have Gust of Wind prepared and cast it the same way. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose when you take the feat). They need no Verbal or Material components. You can cast each once without a slot and regain that use after a Long Rest. You can also cast them with spell slots. You can take only one Wild Talent feat."},"Biokinesis":{"cat":"G","hb":"UA24","d":"Add 1d4 to healing a spell restores. Spare the Dying, Healing Word, Arcane Vigor.","full":"**Bend Life Energy.** When a spell you cast restores Hit Points to a creature, you can roll 1d4 and add it to the Hit Points restored. You can do this a number of times equal to your Proficiency Bonus and regain all uses after a Long Rest.\n**Psionic Talent.** You know the Spare the Dying cantrip. You always have Healing Word prepared. At character level 3 you also always have Arcane Vigor prepared and cast it the same way. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose when you take the feat). They need no Verbal or Material components. You can cast each once without a slot and regain that use after a Long Rest. You can also cast them with spell slots. You can take only one Wild Talent feat."},"Clairsentience":{"cat":"G","hb":"UA24","d":"Advantage on Search checks. Guidance, Detect Evil and Good, See Invisibility.","full":"**Minor Foreknowledge.** When you take the Search action, you can give yourself Advantage on any ability check made as part of it. You can do this a number of times equal to your Proficiency Bonus and regain all uses after a Long Rest.\n**Psionic Talent.** You know the Guidance cantrip. You always have Detect Evil and Good prepared. At character level 3 you also always have See Invisibility prepared and cast it the same way. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose when you take the feat). They need no Verbal or Material components. You can cast each once without a slot and regain that use after a Long Rest. You can also cast them with spell slots. You can take only one Wild Talent feat."},"Cryokinesis":{"cat":"G","hb":"UA24","d":"Change damage to Cold. Ray of Frost, Armor of Agathys, Ice Knife.","full":"**Ice Manipulation.** Once per turn, when you cast a spell or hit with an attack roll and deal Bludgeoning, Piercing, Slashing, or Psychic damage, you can change the damage type to Cold.\n**Psionic Talent.** You know the Ray of Frost cantrip. You always have Armor of Agathys and Ice Knife prepared. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose when you take the feat). They need no Verbal or Material components. You can cast each once without a slot and regain that use after a Long Rest. You can also cast them with spell slots. You can take only one Wild Talent feat."},"Empath":{"cat":"G","hb":"UA24","d":"Advantage on Influence checks. Charm Person and Calm Emotions.","full":"**Emotional Sense.** When you take the Influence action, you can give yourself Advantage on any ability check made as part of it. You can do this a number of times equal to your Proficiency Bonus and regain all uses after a Long Rest.\n**Psionic Talent.** You always have Charm Person prepared. It needs no Verbal component. At character level 3 you also always have Calm Emotions prepared and cast it the same way. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose when you take the feat). They need no Verbal or Material components. You can cast each once without a slot and regain that use after a Long Rest. You can also cast them with spell slots. You can take only one Wild Talent feat."},"Flesh Morpher":{"cat":"G","hb":"UA24","d":"Add Intelligence to Acrobatics and Sleight of Hand. Longstrider and Alter Self.","full":"**Flexible Flesh.** When you make a Dexterity (Acrobatics or Sleight of Hand) check, you gain a bonus equal to your Intelligence modifier (minimum +1). You can do this a number of times equal to your Proficiency Bonus and regain all uses after a Long Rest.\n**Psionic Talent.** You always have Longstrider prepared. At character level 3 you also always have Alter Self prepared and cast it the same way. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose when you take the feat). They need no Verbal or Material components. You can cast each once without a slot and regain that use after a Long Rest. You can also cast them with spell slots. You can take only one Wild Talent feat."},"Mind Whisperer":{"cat":"G","hb":"UA24","d":"Telepathic link at 120 ft. Mind Sliver and Dissonant Whispers.","full":"**Limited Telepathy.** As a Magic action, pick a creature you can see within 120 feet. You form a telepathic link for 1 hour, so you and that creature can talk mentally while within 120 feet of each other. Each of you must mentally use a language the other knows. After you use this you cannot do so again until you finish a Short or Long Rest.\n**Psionic Talent.** You know the Mind Sliver cantrip. You always have Dissonant Whispers prepared. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose when you take the feat). They need no Verbal or Material components. You can cast each once without a slot and regain that use after a Long Rest. You can also cast them with spell slots. You can take only one Wild Talent feat."},"Psi Trickster":{"cat":"G","hb":"UA24","d":"Add Intelligence to Deception and Persuasion. Minor Illusion and Disguise Self.","full":"**Cunning Mind.** When you make a Charisma (Deception or Persuasion) check, you gain a bonus equal to your Intelligence modifier (minimum +1). You can do this a number of times equal to your Proficiency Bonus and regain all uses after a Long Rest.\n**Psionic Talent.** You know the Minor Illusion cantrip. You always have Disguise Self prepared. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose when you take the feat). They need no Verbal or Material components. You can cast each once without a slot and regain that use after a Long Rest. You can also cast them with spell slots. You can take only one Wild Talent feat."},"Psykineticist":{"cat":"G","hb":"UA24","d":"Speed boost on Dash. Telekinetic Fling and Thunderwave.","full":"**Psi Boost.** When you take the Dash action, you can raise your Speed by 10 feet until the start of your next turn. You can do this a number of times equal to your Proficiency Bonus and regain all uses after a Long Rest.\n**Psionic Talent.** You know the Telekinetic Fling cantrip. You always have Thunderwave prepared. Your spells from this feat need no Verbal component. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose when you take the feat). They need no Verbal or Material components. You can cast each once without a slot and regain that use after a Long Rest. You can also cast them with spell slots. You can take only one Wild Talent feat."},"Pyrokinesis":{"cat":"G","hb":"UA24","d":"Change damage to Fire. Produce Flame, Burning Hands, Scorching Ray.","full":"**Firestarter.** Once per turn, when you cast a spell or hit with an attack roll and deal Bludgeoning, Piercing, Slashing, or Psychic damage, you can change the damage type to Fire.\n**Psionic Talent.** You know the Produce Flame cantrip. You always have Burning Hands prepared. At character level 3 you also always have Scorching Ray prepared and cast it the same way. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose when you take the feat). They need no Verbal or Material components. You can cast each once without a slot and regain that use after a Long Rest. You can also cast them with spell slots. You can take only one Wild Talent feat."},"Full Ceremorphosis":{"cat":"G","hb":"UA24","d":"Become a mind flayer: bigger dice, Aberration type, and a talent.","full":"Raise Intelligence by 1, to a maximum of 20.\n**Psionic Energy Dice.** Your Ceremorphosis dice become d10s, or d12s if they already are d10s.\n**Aberration.** Your creature type is Aberration.\n**Illithid Specialization.** Pick one. Brain-Seeking Tentacles: when you hit with an Unarmed Strike as part of the Attack action, you can use both the Damage and Grapple options. You can spend a Psionic Energy Die, roll it, and the target takes Psychic damage equal to the roll plus your Intelligence modifier and subtracts half the roll (round up) from its save against being Grappled. If this drops the target to 0 Hit Points the die isn't spent. Once per turn. Mind Flayer Spells: you always have Detect Thoughts, Levitate, and Mind Blast prepared, cast with Intelligence. You can cast them by spending a Psionic Energy Die instead of a slot, or with slots.\nYou can take this feat again, choosing a different specialization each time.","pre":"Level 12+, two Path of Ceremorphosis feats","asi":["INT"],"fx":{"notes":[["Note","Full Ceremorphosis: creature type is Aberration"]]}},"Illithid Thrallmaker":{"cat":"G","hb":"UA24","d":"Telepathy 10 ft and a free Charm Person that weakens the save.","full":"Raise Intelligence or Charisma by 1, to a maximum of 20.\n**Psionic Energy Dice.** Your Ceremorphosis dice become d8s.\n**Telepathy.** You have Telepathy with a range of 10 feet, or +10 feet if you already have it.\n**Persuasive Presence.** You always have Charm Person prepared, cast with Intelligence. You can cast it by spending a Psionic Energy Die instead of a slot, or with slots. When you spend a die, roll it, and one target subtracts half the roll (round up) from its saving throw.","asi":["INT","CHA"],"needs":"Tadpole Host"},"Tadpole Host":{"cat":"G","hb":"UA24","d":"Mind Sliver and Psionic Energy Dice that add Psychic damage.","full":"Raise Intelligence by 1, to a maximum of 20.\n**Mind Sliver.** You learn the Mind Sliver cantrip, cast with Intelligence.\n**Psionic Power.** You have Psionic Energy Dice equal to your Proficiency Bonus, starting as d6s. Other Path of Ceremorphosis feats change the die size. Features of this path use only these dice, and you can't use a feature that needs a die when they are all spent. You regain them all after a Long Rest.\n**Psionic Overload.** When you deal Psychic damage you can spend a Psionic Energy Die and add its roll to the damage.","pre":"Level 4+","asi":["INT"]},"Tadpole's Safeguard":{"cat":"G","hb":"UA24","d":"Telepathy 10 ft and a free Shield that hurts the attacker.","full":"Raise Constitution or Intelligence by 1, to a maximum of 20.\n**Psionic Energy Dice.** Your Ceremorphosis dice become d8s.\n**Telepathy.** You have Telepathy with a range of 10 feet, or +10 feet if you already have it.\n**Warding Backlash.** You always have Shield prepared, cast with Intelligence. You can cast it by spending a Psionic Energy Die instead of a slot, or with slots. If you spend a die and the attack misses, roll it and the attacker takes Psychic damage equal to the roll.","asi":["CON","INT"],"needs":"Tadpole Host"},"Ulitharid's Might":{"cat":"G","hb":"UA24","d":"Telepathy 10 ft and two extra tentacles that add 5 ft of reach.","full":"Raise Strength, Dexterity, or Constitution by 1, to a maximum of 20.\n**Psionic Energy Dice.** Your Ceremorphosis dice become d8s.\n**Telepathy.** You have Telepathy with a range of 10 feet, or +10 feet if you already have it.\n**Extended Tentacles.** Two long tentacles grow around your mouth. You can make Unarmed Strikes with them, and your reach is 5 feet greater while you use them.","asi":["STR","DEX","CON"],"needs":"Tadpole Host"},"Atoner's Grace":{"cat":"O","hb":"UA24","d":"Hostility doesn't hamper Persuasion, and Disengage or Influence helps nearby creatures.","full":"**Disarming Mien.** A creature's Hostile attitude doesn't impose Disadvantage on your Charisma (Persuasion) checks to influence it.\n**Parley.** When you take the Disengage or Influence action, each creature of your choice within 5 feet has Advantage on the next ability check or saving throw it makes before the start of your next turn."},"Boon of the Bandit King":{"cat":"E","hb":"UA24","d":"Charm a pickpocketing target and never provoke Opportunity Attacks.","full":"**Ability Score Increase.** Pick one ability score and raise it by 1 (maximum 30).\n**Dastardly Charm.** You have Advantage on Dexterity (Sleight of Hand) checks to pick pockets. When you succeed, the target willingly gives up the item and is Charmed for 1 minute or until it takes damage. After you use this you can't use it again until a Short or Long Rest.\n**Uncatchable.** Your movement doesn't provoke Opportunity Attacks.","pre":"Level 19+","asi":["STR","DEX","CON","INT","WIS","CHA"]},"Boon of the Cleansed Heart":{"cat":"E","hb":"UA24","d":"Free Dispel Evil and Good and Necrotic immunity that strikes back with Radiant damage.","full":"**Ability Score Increase.** Pick one ability score and raise it by 1 (maximum 30).\n**Cleanse Heart.** You can cast Dispel Evil and Good without a spell slot, but not its Dismissal function.\n**Radiant Reflection.** You have Immunity to Necrotic damage. When you would take Necrotic damage and aren't Incapacitated, you deal 2d8 Radiant damage to each creature of your choice within a 10-foot Emanation.","pre":"Level 19+","asi":["STR","DEX","CON","INT","WIS","CHA"],"fx":{"imm":["Necrotic"]}},"Boon of the Hunter's Eye":{"cat":"E","hb":"UA24","d":"Knock out a weakened target and learn a creature's defenses at Initiative.","full":"**Ability Score Increase.** Pick one ability score and raise it by 1 (maximum 30).\n**Quick Capture.** When you damage a creature you mean to knock out, and it has 20 or fewer Hit Points left, it drops to 0 Hit Points.\n**Studied Hunter.** When you roll Initiative, pick a creature you see. You learn whether it has any Immunity, Resistance, or Vulnerability, and which.","pre":"Level 19+","asi":["STR","DEX","CON","INT","WIS","CHA"]},"Boon of Unwavering Devotion":{"cat":"E","hb":"UA24","d":"Immune to possession and illusions, and force a Wisdom save reroll.","full":"**Ability Score Increase.** Pick one ability score and raise it by 1 (maximum 30).\n**Possession Immunity.** You automatically pass saves to avoid or end possession.\n**See Through Illusions.** Visual illusions look transparent to you and you automatically pass saves against them.\n**Undeniable Confidence.** Right after a creature you see succeeds on a Wisdom save against an effect you created, you can use your Reaction to make it reroll and use the new roll. You can't do this again until you roll Initiative or finish a Short or Long Rest.","pre":"Level 19+","asi":["STR","DEX","CON","INT","WIS","CHA"]},"Raised by Cultists":{"cat":"O","hb":"UA24","d":"Heroic Inspiration when Bloodied and Advantage on an ally's Concentration save.","full":"**Bloody Revelation.** When you become Bloodied, you can use your Reaction to gain Heroic Inspiration.\n**Communal Caster.** When an ally within 5 feet makes a Constitution save to keep Concentration, you can use your Reaction to give it Advantage on the save."},"Trapper":{"cat":"O","hb":"UA24","d":"Better Study and travel checks and stronger Hunting Traps.","full":"**Eye for Detail.** You have Advantage on Intelligence (Investigation) checks you make as part of the Study action.\n**Swift Tracker.** Traveling at a Travel Pace gives you no Disadvantage on Wisdom (Perception or Survival) checks, and Advantage on them.\n**Trap Expert.** You can set a Hunting Trap as a Bonus Action instead of a Utilize action, and add your Proficiency Bonus to the save DC to avoid it and the check DC to escape it."},"Underhanded":{"cat":"O","hb":"UA24","d":"Move 10 ft after Initiative and trip a creature that misses you.","full":"**Elusive.** Right after you roll Initiative, you can move up to 10 feet.\n**Fight Dirty.** When a creature one size larger than you or smaller misses you with an Opportunity Attack, you can use your Reaction to knock it Prone. You need a free hand."},"Arcane Restoration":{"cat":"G","hb":"UA24","d":"Regain spell slots when you consume a soul.","full":"Raise Intelligence, Wisdom, or Charisma by 1, to a maximum of 20.\n**Essence Rejuvenation.** When you use Soul Siphon to consume a soul, you can recover expended spell slots with a combined level of 4 or less. After you use this you can't use it again until a Short or Long Rest.","asi":["INT","WIS","CHA"],"needs":"Lich Initiate"},"Death Knight Ascension":{"cat":"G","hb":"UA24","d":"Undead type, necrotic and poison resistance, and Hellfire Orb.","full":"Raise Strength or Charisma by 1, to a maximum of 20.\n**Undead.** Your creature type is Undead.\n**Unholy Anatomy.** You have Resistance to Necrotic and Poison damage, and gain no Exhaustion from dehydration, malnutrition, or suffocation.\n**Hellfire Orb.** Magic action, spend 1 to 5 Death Points: throw an orb of hellfire at a point you see within 120 feet. Each creature in a 20-foot-radius Sphere makes a Dexterity save (DC 8 + Charisma modifier + Proficiency Bonus). A failure takes 2d6 Fire and 2d6 Necrotic damage per Death Point spent, a success takes half.","pre":"Level 12+, two Path of the Death Knight feats","asi":["STR","CHA"],"fx":{"res":["Necrotic","Poison"]}},"Death Knight Initiate":{"cat":"G","hb":"UA24","d":"Death Points and a free Wrathful Smite that weakens saves.","full":"Raise Strength or Charisma by 1, to a maximum of 20.\n**Death Points.** You have Death Points equal to your Proficiency Bonus and regain them all after a Long Rest. Path of the Death Knight benefits spend them. This feat gives you Dread Strike.\n**Dread Strike.** You always have Wrathful Smite prepared, cast with Charisma. You can cast it by spending 1 Death Point instead of a slot, or with slots. When you spend Death Points on it, the target has Disadvantage on Wisdom saves to avoid or end its effect.","pre":"Level 4+, Weapon Mastery","asi":["STR","CHA"]},"Deathly Presence":{"cat":"G","hb":"UA24","d":"Free Fear that also deals Psychic damage.","full":"Raise Strength, Constitution, or Charisma by 1, to a maximum of 20.\n**Awful Presence.** You always have Fear prepared, cast with Charisma. You can cast it by spending a Death Point instead of a slot, or with slots. When you spend Death Points on it, each creature that fails its save takes 2d6 Psychic damage on top of the normal effects.","pre":"Level 8+, Death Knight Initiate","asi":["STR","CON","CHA"],"needs":"Death Knight Initiate"},"Dread Authority":{"cat":"G","hb":"UA24","d":"Free Command that Undead save against with Disadvantage.","full":"Raise Constitution or Charisma by 1, to a maximum of 20.\n**Dread Command.** You always have Command prepared, cast with Charisma. You can cast it by spending a Death Point instead of a slot, or with slots. When you spend Death Points on it, Undead targets have Disadvantage on the save.","asi":["CON","CHA"],"needs":"Death Knight Initiate"},"Harbinger of Doom":{"cat":"G","hb":"UA24","d":"Free Bane that subtracts 1d6.","full":"Raise Strength, Constitution, or Charisma by 1, to a maximum of 20.\n**Ill Omen.** You always have Bane prepared, cast with Charisma. You can cast it by spending a Death Point instead of a slot, or with slots. When you spend Death Points on it, affected targets subtract 1d6 instead of 1d4 from attack rolls and saves.","asi":["STR","CON","CHA"],"needs":"Death Knight Initiate"},"Lich Ascension":{"cat":"G","hb":"UA24","d":"Undead type, resistances, free Fear, and a way to re-form.","full":"Raise Intelligence, Wisdom, or Charisma by 1, to a maximum of 20.\n**Undead.** Your creature type is Undead.\n**Unholy Anatomy.** You have Resistance to Necrotic and Poison damage, and gain no Exhaustion from dehydration, malnutrition, or suffocation.\n**Frightening Gaze.** You learn Fear if you don't know it and always have it prepared. Intelligence, Wisdom, or Charisma is its spellcasting ability (choose when you take this feat). You can cast it without a slot a number of times equal to your spellcasting ability modifier (minimum 1), regaining all uses after a Long Rest.\n**Rejuvenation.** If you die with a spirit jar and aren't revived first, you re-form in 1d10 days with all your Hit Points in the nearest free space within 5 feet of the jar.","pre":"Level 12+, two Path of the Lich feats","asi":["INT","WIS","CHA"],"fx":{"res":["Necrotic","Poison"]}},"Lich Initiate":{"cat":"G","hb":"UA24","d":"A spirit jar and Soul Siphon bonus damage.","full":"Raise Intelligence, Wisdom, or Charisma by 1, to a maximum of 20. Pick that ability as your spellcasting ability for this feat's features.\n**Creating Your Spirit Jar.** Choose a Tiny object of great meaning to you and spend a Long Rest anchoring your soul to it. You can have one spirit jar. A second jar destroys the first.\n**Spirit Jar Destruction.** The jar's AC equals your spell save DC and its Hit Points equal your spellcasting ability modifier plus your character level. If it is destroyed you gain 2 Exhaustion levels and can't use Soul Siphon until you make a new one.\n**Soul Siphon.** When you drop a Humanoid enemy to 0 Hit Points, or someone else does within 10 feet of you, you can consume its soul (no action). On your next turn the first creature you hit with an attack takes extra Necrotic damage equal to 1d6 + your spellcasting ability modifier. Only True Resurrection or Wish restores a soul consumed this way.","pre":"Level 4+, Spellcasting","asi":["INT","WIS","CHA"]},"Transfer Life":{"cat":"G","hb":"UA24","d":"Give a creature Temporary Hit Points when you consume a soul.","full":"Raise Intelligence, Wisdom, or Charisma by 1, to a maximum of 20.\n**Soul Transference.** When you use Soul Siphon to consume a soul, pick a creature within 60 feet. It gains Temporary Hit Points equal to your Proficiency Bonus plus your spellcasting ability modifier (minimum 1).","asi":["INT","WIS","CHA"],"needs":"Lich Initiate"},"Undead Grasp":{"cat":"G","hb":"UA24","d":"Chill Touch that can paralyze.","full":"Raise Intelligence, Wisdom, or Charisma by 1, to a maximum of 20.\n**Paralyzing Touch.** You learn Chill Touch, or another cantrip if you know it. Intelligence, Wisdom, or Charisma is its spellcasting ability (choose when you take this feat). When you deal damage with Chill Touch you can spend a level 1+ spell slot. The target takes extra Necrotic damage of 1d10 per slot level and makes a Constitution save against your spell save DC or is Paralyzed until the start of your next turn.","asi":["INT","WIS","CHA"],"needs":"Lich Initiate"},"Unholy Steed":{"cat":"G","hb":"UA24","d":"Free Find Steed with a Fiend mount.","full":"Raise Strength or Constitution by 1, to a maximum of 20.\n**Spectral Steed.** You always have Find Steed prepared, cast with Charisma. You can cast it by spending Death Points instead of a slot, or with slots. When you spend Death Points on it, the steed is a Fiend and targets you choose have Disadvantage on the Wisdom save against its Fell Glare.","pre":"Level 8+, Death Knight Initiate","asi":["STR","CON"],"needs":"Death Knight Initiate"}};
var FTLU=[{"src":"feat","owner":"Biokinesis","feature":"Biokinesis","n":"Bend Life Energy","lvl":1,"max":"pb","reset":"long","tag":"Add 1d4 to spell healing"},{"src":"feat","owner":"Clairsentience","feature":"Clairsentience","n":"Minor Foreknowledge","lvl":1,"max":"pb","reset":"long","tag":"Advantage on a Search check"},{"src":"feat","owner":"Empath","feature":"Empath","n":"Emotional Sense","lvl":1,"max":"pb","reset":"long","tag":"Advantage on an Influence check"},{"src":"feat","owner":"Flesh Morpher","feature":"Flesh Morpher","n":"Flexible Flesh","lvl":1,"max":"pb","reset":"long","tag":"Add Intelligence to a check"},{"src":"feat","owner":"Mind Whisperer","feature":"Mind Whisperer","n":"Limited Telepathy","lvl":1,"max":1,"reset":"short","tag":"Magic action, 1 hour link"},{"src":"feat","owner":"Psi Trickster","feature":"Psi Trickster","n":"Cunning Mind","lvl":1,"max":"pb","reset":"long","tag":"Add Intelligence to a check"},{"src":"feat","owner":"Psykineticist","feature":"Psykineticist","n":"Psi Boost","lvl":1,"max":"pb","reset":"long","tag":"+10 ft Speed on Dash"},{"src":"feat","owner":"Tadpole Host","feature":"Tadpole Host","n":"Psionic Energy Dice (Ceremorphosis)","lvl":1,"max":"pb","reset":"long","tag":"d6, larger with other path feats"},{"src":"feat","owner":"Boon of the Bandit King","feature":"Boon of the Bandit King","n":"Dastardly Charm","lvl":1,"max":1,"reset":"short","tag":"On a successful pickpocket"},{"src":"feat","owner":"Boon of Unwavering Devotion","feature":"Boon of Unwavering Devotion","n":"Undeniable Confidence","lvl":1,"max":1,"reset":"short","tag":"Reaction, also resets on Initiative"},{"src":"feat","owner":"Arcane Restoration","feature":"Arcane Restoration","n":"Essence Rejuvenation","lvl":1,"max":1,"reset":"short","tag":"Recover slots of combined level 4"},{"src":"feat","owner":"Death Knight Initiate","feature":"Death Knight Initiate","n":"Death Points","lvl":1,"max":"pb","reset":"long","tag":"Path of the Death Knight"},{"src":"feat","owner":"Lich Ascension","feature":"Lich Ascension","n":"Frightening Gaze (Fear)","lvl":1,"max":{"f":"mod:INT","min":1},"reset":"long","tag":"No slot, uses your spellcasting modifier"}];
