var SPR=[["Abi-Dalzim's Horrid Wilting (UA)",8,"Necromancy",["Psion","Sorcerer","Wizard"],"Action","150 ft","V, S, M","Instantaneous",0,0,"CON","You drain the moisture from every creature in a 30-foot Cube centered on a point within 150 feet.","UA24",["Psion","Sorcerer","Wizard"]],["Bleeding Darkness",3,"Evocation",["Psion","Warlock","Wizard"],"Action","60 ft","V, S, M","Up to 1 minute",1,0,"CON","You open an inky void in a 10-foot-radius Sphere at a point you can see above you within 60 feet.","UA24",["Psion","Warlock","Wizard"]],["Ectoplasmic Trail",2,"Necromancy",["Psion","Warlock"],"Bonus Action","Self","V, S","Instantaneous",0,0,"","You wrap yourself in spirits that leave ectoplasm behind you until the end of your turn.","UA24",["Psion","Warlock"]],["Ego Whip",2,"Enchantment",["Psion"],"Reaction","120 ft","V","Instantaneous",0,0,"CHA","Reaction, taken when a creature you can see within 30 feet makes a Charisma-based ability check or save.","UA24",["Psion"]],["Enemies Abound (UA)",3,"Enchantment",["Bard","Psion","Sorcerer","Warlock","Wizard"],"Action","120 ft","V, S","Up to 1 minute",1,0,"INT","Pick a creature you can see within 120 feet.","UA24",["Bard","Psion","Sorcerer","Warlock","Wizard"]],["Intellect Fortress (UA)",3,"Abjuration",["Artificer","Bard","Psion","Sorcerer","Warlock","Wizard"],"Action","30 ft","V","Up to 1 hour",1,0,"CHA","For the duration, one willing creature you can see within 30 feet has Resistance to Psychic damage and Advantage on Intelligence, Wisdom, and Charisma saves.","UA24",["Artificer","Bard","Psion","Sorcerer","Warlock","Wizard"]],["Life Inversion Field",4,"Abjuration",["Cleric","Psion","Sorcerer"],"Action","Self","V, S","Up to 1 minute",1,0,"CON","A 30-foot Emanation of psionic energy surrounds you for the duration.","UA24",["Cleric","Psion","Sorcerer"]],["Life Siphon (UA)",1,"Evocation",["Psion"],"Action","120 ft","S","Instantaneous",0,0,"","You fire an orb of psionic energy fueled by your life force at a creature you can see within 120 feet.","UA24",["Psion"]],["Mental Prison (UA)",6,"Illusion",["Bard","Psion","Sorcerer","Wizard"],"Action","60 ft","S","Up to 1 minute",1,0,"INT","You trap a creature in an illusory cell only it perceives.","UA24",["Bard","Psion","Sorcerer","Wizard"]],["Mind Blast",6,"Evocation",["Psion"],"Action","Self","S","Instantaneous",0,0,"INT","A concussive psionic burst in a 60-foot Cone deals 6d8 Psychic damage and can Stun.","UA24",["Psion"]],["Psionic Blast (UA)",6,"Evocation",["Psion","Wizard"],"Action","Self","V, S","Instantaneous",0,0,"INT","You release a concussive burst of psionic energy.","UA24",["Psion","Wizard"]],["Psychic Scream (UA)",9,"Enchantment",["Bard","Psion","Sorcerer","Warlock"],"Action","90 ft","S","Instantaneous",0,0,"INT","You blast the minds of up to ten creatures you can see within 90 feet.","UA24",["Bard","Psion","Sorcerer","Warlock"]],["Raulothim's Psychic Lance (UA)",4,"Enchantment",["Bard","Psion","Sorcerer","Warlock","Wizard"],"Action","120 ft","V","Instantaneous",0,0,"INT","You fire a shimmering lance of psychic power from your forehead at a creature you can see within 120 feet.","UA24",["Bard","Psion","Sorcerer","Warlock","Wizard"]],["Summon Astral Entity",3,"Conjuration",["Psion","Sorcerer","Warlock","Wizard"],"Action","90 ft","V, S, M","Up to 1 hour",1,0,"","You call the spirit of a psionic entity into an empty space you can see within 90 feet.","UA24",["Psion","Sorcerer","Warlock","Wizard"]],["Tasha's Mind Whip (UA)",2,"Enchantment",["Psion","Sorcerer","Wizard"],"Action","90 ft","V","Instantaneous",0,0,"INT","You lash out at a creature you can see within 90 feet.","UA24",["Psion","Sorcerer","Wizard"]],["Telekinetic Crush",3,"Transmutation",["Psion","Sorcerer","Warlock"],"Action","120 ft","V","Instantaneous",0,0,"STR","You make a field of crushing force in a 30-foot Cube within 120 feet.","UA24",["Psion","Sorcerer","Warlock"]],["Telekinetic Fling",0,"Evocation",["Psion"],"Action","60 ft","S","Instantaneous",0,0,"","Choose a nonmagical object of 1 to 5 pounds within 10 feet of you that is not worn or carried.","UA24",["Psion"]],["Thought Form",6,"Transmutation",["Psion"],"Bonus Action","Self","V, M","Up to 1 minute",1,0,"","You turn briefly into a psionic spirit. Until the spell ends you gain these benefits.","UA24",["Psion"]]];
var SPF={"Abi-Dalzim's Horrid Wilting (UA)":"You drain the moisture from every creature in a 30-foot Cube centered on a point within 150 feet. Each creature in the Cube makes a Constitution save. It takes 12d8 Necrotic damage on a failure, or half on a success. Constructs automatically succeed and Plant creatures automatically fail. Nonmagical plants that are not creatures wither and die at once. Material: a bit of sponge.","Bleeding Darkness":"You open an inky void in a 10-foot-radius Sphere at a point you can see above you within 60 feet. Magical Darkness fills a 10-foot-radius, 40-foot-tall Cylinder from the Sphere until the start of your next turn. The Cylinder is Difficult Terrain and no light can brighten it. When it appears, each creature in it makes a Constitution save or takes 3d8 Cold damage and is Blinded until the end of its next turn. A creature also saves when it first enters on a turn or ends its turn there, once per turn. As a Magic action you can move the Sphere up to 20 feet horizontally and make it pour Darkness again until the start of your next turn. Material: a vial of rare ink worth 50+ GP.\n\n**Using a Higher-Level Spell Slot.** The damage rises by 1d8 per slot level above 3.","Ectoplasmic Trail":"You wrap yourself in spirits that leave ectoplasm behind you until the end of your turn. You can move through occupied spaces as if they were Difficult Terrain and your movement provokes no Opportunity Attacks. If you end your turn in such a space, you return to the last empty space you were in. Each creature whose space you enter is covered in ectoplasm until the end of your next turn, which cuts its Speed by 10 feet and deals 2d8 Necrotic damage at the start of its turn. A creature is covered only once per turn.\n\n**Using a Higher-Level Spell Slot.** Your Speed rises by 10 feet per slot level above 2 while you are cloaked.","Ego Whip":"Reaction, taken when a creature you can see within 30 feet makes a Charisma-based ability check or save. The creature makes a Charisma save. On a failure it subtracts 1d8 from the check or save.","Enemies Abound (UA)":"Pick a creature you can see within 120 feet. It makes an Intelligence save or is Frightened for the duration and can no longer tell friend from foe. It treats all creatures it sees as enemies. When it picks a creature other than itself for an attack, spell, or ability, it picks at random among the creatures it can see in range. It must make an Opportunity Attack whenever it can. Each time it takes damage it repeats the save, and a success ends the spell.","Intellect Fortress (UA)":"For the duration, one willing creature you can see within 30 feet has Resistance to Psychic damage and Advantage on Intelligence, Wisdom, and Charisma saves.\n\n**Using a Higher-Level Spell Slot.** You can target one more creature per slot level above 3.","Life Inversion Field":"A 30-foot Emanation of psionic energy surrounds you for the duration. When you create it you regain 4d8 Hit Points. Whenever you regain Hit Points, you can pick a creature you can see in the aura. It makes a Constitution save or takes Necrotic damage equal to half the Hit Points you regained (round up). A creature saves only once per turn.\n\n**Using a Higher-Level Spell Slot.** The healing rises by 1d8 per slot level above 4.","Life Siphon (UA)":"You fire an orb of psionic energy fueled by your life force at a creature you can see within 120 feet. Make a ranged spell attack. On a hit the target takes 1d10 Psychic damage, and you can spend one Hit Point Die to add 1d10 damage.\n\n**Using a Higher-Level Spell Slot.** The damage rises by 1d10, and you can spend one more Hit Point Die, per slot level above 1.","Mental Prison (UA)":"You trap a creature in an illusory cell only it perceives. One creature you can see within 60 feet makes an Intelligence save or takes 8d10 Psychic damage and is Charmed for the duration. On a success it takes half damage and the spell ends. While Charmed it is Restrained and sees the area around it as dangerous in a way you choose, such as flames, floating razors, or hideous maws. It cannot see or hear anything past the illusion. If it is moved out, makes a melee attack through the illusion, or reaches any part of itself through it, it takes 5d10 Psychic damage and the spell ends.","Mind Blast":"A concussive psionic burst in a 60-foot Cone deals 6d8 Psychic damage and can Stun. Each creature in the Cone makes an Intelligence save. On a failure it takes 6d8 Psychic damage and is Stunned until the start of your next turn. On a success it takes half damage only.\n\n**Using a Higher-Level Spell Slot.** The damage rises by 1d8 per slot level above 6.","Psionic Blast (UA)":"You release a concussive burst of psionic energy. Each creature in a 60-foot Cone from you makes an Intelligence save. On a failure it takes 6d8 Psychic damage and is Stunned until the start of your next turn. On a success it takes half damage only.\n\n**Using a Higher-Level Spell Slot.** The damage rises by 1d8 per slot level above 6.","Psychic Scream (UA)":"You blast the minds of up to ten creatures you can see within 90 feet. Creatures with Intelligence 2 or lower are unaffected. Each target makes an Intelligence save. On a failure it takes 14d6 Psychic damage and is Stunned. On a success it takes half damage only. A target reduced to 0 Hit Points by this damage has its head burst, if it has one. At the end of each of its turns, a Stunned target repeats the save and a success ends the condition.","Raulothim's Psychic Lance (UA)":"You fire a shimmering lance of psychic power from your forehead at a creature you can see within 120 feet. Or you can speak the true name of a creature (not a title or nickname). If the named target is in range it becomes the target even if you cannot see it. If it is out of range or the name is wrong, the lance fades with no effect. The target makes an Intelligence save. On a failure it takes 7d6 Psychic damage and is Incapacitated until the start of your next turn. On a success it takes half damage only.\n\n**Using a Higher-Level Spell Slot.** The damage rises by 1d6 per slot level above 4.","Summon Astral Entity":"You call the spirit of a psionic entity into an empty space you can see within 90 feet. It uses the Psionic Spirit stat block. Choose Crystal Entity, Ectoplasmic Entity, or Ghostly Entity, which sets some details of the stat block. It is your ally and acts on your Initiative, right after you. It obeys your spoken commands with no action from you. With no command it takes the Dodge action and moves to avoid danger. It vanishes at 0 Hit Points or when the spell ends. Material: a gem or crystal worth 300+ GP.\n\n**Using a Higher-Level Spell Slot.** Use the slot's level as the spell level in the stat block.","Tasha's Mind Whip (UA)":"You lash out at a creature you can see within 90 feet. It makes an Intelligence save. On a failure it takes 3d6 Psychic damage and cannot make Opportunity Attacks until the end of its next turn. On its next turn it must choose a move, an action, or a Bonus Action, and gets only that one. On a success it takes half damage only.\n\n**Using a Higher-Level Spell Slot.** You can target one more creature per slot level above 2.","Telekinetic Crush":"You make a field of crushing force in a 30-foot Cube within 120 feet. Each creature in it makes a Strength save. On a failure it takes 5d6 Force damage and falls Prone. On a success it takes half damage only.\n\n**Using a Higher-Level Spell Slot.** The damage rises by 1d6 per slot level above 3.","Telekinetic Fling":"Choose a nonmagical object of 1 to 5 pounds within 10 feet of you that is not worn or carried. Wreathe it in psionic energy and fire it at a creature within 60 feet. Make a ranged spell attack. On a hit the target takes 1d10 Force damage. Hit or miss, the object falls to the ground undamaged.\n\n**Cantrip Upgrade.** The damage rises to 2d10 at level 5, 3d10 at level 11, and 4d10 at level 17.","Thought Form":"You turn briefly into a psionic spirit. Until the spell ends you gain these benefits. Ghostly Form: Immunity to Poison and Psychic damage and to the Exhaustion condition. Incorporeal Movement: Fly Speed 60 feet with hover, and you can move through occupied spaces as if they were Difficult Terrain. If you end your turn in one you take 1d10 Force damage, and if the spell ends there you return to the last empty space you were in. Psionic Recharge: as a Magic action touch a creature (you can pick yourself) and roll 1d6. It regains one spent spell slot of a level up to half the roll (round up). A creature that regains a slot this way cannot do so again until it finishes a Long Rest. Material: brain matter in a vessel worth 500+ GP."};
